class BoundedQueue {
  std::mutex m_;
  std::condition_variable not_full_, not_empty_;
  std::deque<Message> q_;  std::size_t cap_;
public:
  void put(Message m) {
    std::unique_lock lk{m_};
    not_full_.wait(lk, [&] { return q_.size() < cap_; });
    q_.push_back(std::move(m));
    not_empty_.notify_one();
  }
};

