class Message_Queue {
  ACE_Thread_Mutex monitor_lock_;
  ACE_Condition<ACE_Thread_Mutex> not_full_{monitor_lock_}, not_empty_{monitor_lock_};
public:
  void put(const Message &msg) {
    Guard<ACE_Thread_Mutex> guard(monitor_lock_);   // Scoped Locking
    while (full_i()) not_full_.wait();              // predicate loop
    put_i(msg);
    not_empty_.signal();
  }
};
